// Backend configuration (Directive 25 Phase 5/12).
// Secrets are Secret Manager secrets bound to the functions that need them;
// in the emulator they come from functions/.secret.local (git-ignored,
// generated by scripts/directive25/prepareEmulatorSecrets.mjs).
// Nothing here is ever shipped to the browser.
import { defineBoolean, defineSecret, defineString } from 'firebase-functions/params';

export const RAZORPAY_KEY_ID = defineString('RAZORPAY_KEY_ID', { default: '' });
export const RAZORPAY_KEY_SECRET = defineSecret('RAZORPAY_KEY_SECRET');
export const RAZORPAY_WEBHOOK_SECRET = defineSecret('RAZORPAY_WEBHOOK_SECRET');
/** Real payments stay OFF until a real provider test has been completed. */
export const PAYMENTS_ENABLED = defineBoolean('PAYMENTS_ENABLED', { default: false });

// The Functions region comes from DSBC_FUNCTIONS_REGION, checked against
// config/environments.json by shared/environment.ts (Directive 27).
